insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('e0000000-0000-0000-0000-000000000001', 'mrcp1', '5ee1985d-25fc-4878-ad2a-b9268266ef7b',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('e0000000-0000-0000-0000-000000000001', 'A', 'Middle cerebral artery', true, 'Correct. Face- and arm-predominant contralateral weakness, homonymous hemianopia and aphasia (in a dominant-hemisphere lesion) are the classic triad of MCA territory infarction.', 1),
('e0000000-0000-0000-0000-000000000001', 'B', 'Anterior cerebral artery', false, 'Ruled out because ACA occlusion causes leg-predominant weakness with relative sparing of the face and arm, the opposite pattern seen here.', 2),
('e0000000-0000-0000-0000-000000000001', 'C', 'Posterior cerebral artery', false, 'Ruled out because PCA occlusion typically causes isolated homonymous hemianopia with macular sparing, without the dense hemiparesis or aphasia described.', 3),
('e0000000-0000-0000-0000-000000000001', 'D', 'Basilar artery', false, 'Ruled out because basilar occlusion classically causes bilateral signs, cranial nerve palsies, or locked-in syndrome, not this unilateral cortical pattern.', 4),
('e0000000-0000-0000-0000-000000000001', 'E', 'Lacunar (lenticulostriate) infarct', false, 'Ruled out because lacunar strokes typically produce a pure motor or pure sensory deficit without cortical signs such as aphasia or hemianopia.', 5),
('e0000000-0000-0000-0000-000000000002', 'A', 'Total anterior circulation infarct', false, 'Ruled out because TACI requires a combination of motor/sensory deficit, homonymous hemianopia, and higher cortical dysfunction; only pure motor weakness is present here.', 1),
('e0000000-0000-0000-0000-000000000002', 'B', 'Partial anterior circulation infarct', false, 'Ruled out because PACI involves two of the three TACI criteria; this patient has an isolated motor deficit with no cortical or visual field signs.', 2),
('e0000000-0000-0000-0000-000000000002', 'C', 'Posterior circulation infarct', false, 'Ruled out because POCI typically causes cerebellar, brainstem, or isolated visual signs, not an isolated pure motor hemiparesis.', 3),
('e0000000-0000-0000-0000-000000000002', 'D', 'Lacunar infarct', true, 'Correct. Pure motor hemiparesis affecting face, arm and leg equally, without cortical signs, in a patient with vascular risk factors (hypertension, diabetes), is the classic presentation of a lacunar infarct from small-vessel (lenticulostriate) disease.', 4),
('e0000000-0000-0000-0000-000000000002', 'E', 'Subarachnoid haemorrhage', false, 'Ruled out because SAH classically presents with sudden severe (thunderclap) headache and meningism, not an isolated focal motor deficit with a normal CT.', 5),
('e0000000-0000-0000-0000-000000000003', 'A', 'Anterior inferior cerebellar artery', false, 'Ruled out because AICA occlusion causes lateral pontine syndrome, typically with ipsilateral facial weakness and deafness, features not described here.', 1),
('e0000000-0000-0000-0000-000000000003', 'B', 'Middle cerebral artery', false, 'Ruled out because MCA occlusion causes a cortical hemispheric syndrome (hemiparesis, aphasia, hemianopia), not the crossed brainstem pattern described.', 2),
('e0000000-0000-0000-0000-000000000003', 'C', 'Superior cerebellar artery', false, 'Ruled out because SCA occlusion classically causes ipsilateral limb ataxia and contralateral pain/temperature loss without the bulbar and Horner features described.', 3),
('e0000000-0000-0000-0000-000000000003', 'D', 'Anterior spinal artery', false, 'Ruled out because anterior spinal artery occlusion causes bilateral motor and spinothalamic loss below the lesion with preserved dorsal column function, not this brainstem pattern.', 4),
('e0000000-0000-0000-0000-000000000003', 'E', 'Posterior inferior cerebellar artery', true, 'Correct. Crossed sensory loss (ipsilateral face, contralateral body), ipsilateral Horner syndrome, and bulbar signs (dysphagia, hoarseness) with vertigo are the hallmark of lateral medullary (Wallenberg) syndrome, caused by PICA or vertebral artery occlusion.', 5),
('e0000000-0000-0000-0000-000000000004', 'A', 'Reassure and discharge with no further action', false, 'Ruled out because a TIA carries a significant short-term risk of completed stroke and mandates urgent specialist assessment, not simple reassurance.', 1),
('e0000000-0000-0000-0000-000000000004', 'B', 'Start aspirin 300 mg immediately and refer for specialist assessment within 24 hours', true, 'Correct. NICE guidance recommends immediate aspirin 300 mg (unless contraindicated) and specialist assessment within 24 hours for a suspected TIA, given the high early risk of stroke, particularly in this patient with vascular risk factors.', 2),
('e0000000-0000-0000-0000-000000000004', 'C', 'Arrange outpatient neurology review within 4 weeks', false, 'Ruled out because this delay is too long; high-risk TIA patients require specialist assessment within 24 hours, not weeks.', 3),
('e0000000-0000-0000-0000-000000000004', 'D', 'Admit for thrombolysis', false, $x$Ruled out because thrombolysis is for acute ischaemic stroke with persisting deficit within the treatment window; this patient's symptoms have already fully resolved.$x$, 4),
('e0000000-0000-0000-0000-000000000004', 'E', 'Start warfarin anticoagulation pending investigation', false, 'Ruled out because anticoagulation before confirming the mechanism (e.g. excluding haemorrhage, establishing whether AF is present) is inappropriate; antiplatelet therapy is first-line pending assessment.', 5),
('e0000000-0000-0000-0000-000000000005', 'A', 'Aspirin 300 mg alone', false, 'Ruled out because aspirin alone is used when thrombolysis is contraindicated or the window has passed; this patient is eligible for and should receive thrombolysis first.', 1),
('e0000000-0000-0000-0000-000000000005', 'B', 'Mechanical thrombectomy alone without thrombolysis', false, 'Ruled out because thrombectomy is reserved for confirmed large-vessel occlusion on imaging and is typically combined with, not substituted for, thrombolysis when both are indicated and available within window.', 2),
('e0000000-0000-0000-0000-000000000005', 'C', 'Withhold treatment until a 24-hour repeat CT', false, 'Ruled out because delaying treatment in a patient within the thrombolysis window worsens outcome -- "time is brain."', 3),
('e0000000-0000-0000-0000-000000000005', 'D', 'Full-dose therapeutic anticoagulation with heparin', false, 'Ruled out because early full-dose anticoagulation in acute ischaemic stroke increases haemorrhagic transformation risk and is not standard first-line therapy.', 4),
('e0000000-0000-0000-0000-000000000005', 'E', 'Intravenous alteplase', true, 'Correct. She presents within the 4.5-hour thrombolysis window with a confirmed ischaemic stroke (no haemorrhage on CT) and no contraindications; IV alteplase is indicated, with blood pressure controlled first if it exceeds the treatment threshold.', 5),
('e0000000-0000-0000-0000-000000000006', 'A', 'Lumbar puncture for xanthochromia', true, 'Correct. When CT is normal but clinical suspicion for SAH remains high, lumbar puncture performed at least 12 hours after symptom onset (to allow xanthochromia to develop) is the next investigation, as early CT can miss up to 5-10% of SAH.', 1),
('e0000000-0000-0000-0000-000000000006', 'B', 'Repeat CT head in 24 hours', false, 'Ruled out because delaying investigation risks missing a subarachnoid haemorrhage that requires urgent diagnosis and treatment; a more definitive test is needed sooner.', 2),
('e0000000-0000-0000-0000-000000000006', 'C', 'MRI brain without contrast', false, 'Ruled out because MRI is less sensitive than CT for acute SAH and is not the standard next step when CT is negative; LP remains the investigation of choice.', 3),
('e0000000-0000-0000-0000-000000000006', 'D', 'Discharge with simple analgesia', false, 'Ruled out because a normal CT does not exclude SAH, and failure to investigate further risks missing a life-threatening diagnosis.', 4),
('e0000000-0000-0000-0000-000000000006', 'E', 'Empirical treatment for migraine', false, 'Ruled out because thunderclap headache reaching maximal intensity within seconds is atypical for migraine and mandates exclusion of SAH first.', 5),
('e0000000-0000-0000-0000-000000000007', 'A', 'Subdural haematoma', false, 'Ruled out because subdural haematomas appear as crescent-shaped (concave) collections that can cross suture lines, not the biconvex lens shape described.', 1),
('e0000000-0000-0000-0000-000000000007', 'B', 'Extradural haematoma', true, 'Correct. A lucid interval followed by rapid deterioration, a biconvex hyperdensity confined by suture lines, and an ipsilateral fixed dilated pupil (uncal herniation compressing the third nerve) are classic for extradural haematoma, typically from middle meningeal artery injury after a temporal (pterion) blow.', 2),
('e0000000-0000-0000-0000-000000000007', 'C', 'Subarachnoid haemorrhage', false, 'Ruled out because SAH typically shows diffuse hyperdensity within the subarachnoid space and sulci, not a focal biconvex extra-axial collection.', 3),
('e0000000-0000-0000-0000-000000000007', 'D', 'Diffuse axonal injury', false, 'Ruled out because diffuse axonal injury typically causes immediate, prolonged coma without a lucid interval, and CT often appears normal or shows scattered small haemorrhages rather than a focal collection.', 4),
('e0000000-0000-0000-0000-000000000007', 'E', 'Intracerebral haemorrhage', false, 'Ruled out because intracerebral haemorrhage is an intra-axial (within brain parenchyma) bleed, not the extra-axial biconvex collection described.', 5),
('e0000000-0000-0000-0000-000000000008', 'A', 'Idiopathic intracranial hypertension', false, 'Ruled out because although IIH also causes headache and papilloedema, it does not typically present with focal seizures, and the postpartum hypercoagulable state points to a thrombotic cause here.', 1),
('e0000000-0000-0000-0000-000000000008', 'B', 'Bacterial meningitis', false, 'Ruled out because there is no fever, neck stiffness, or systemic infective picture described, and meningitis would not be confirmed by MRI venography.', 2),
('e0000000-0000-0000-0000-000000000008', 'C', 'Migraine with aura', false, 'Ruled out because migraine does not cause papilloedema or seizures, and would not require confirmation by venography.', 3),
('e0000000-0000-0000-0000-000000000008', 'D', 'Ischaemic stroke', false, 'Ruled out because the postural headache, papilloedema and venography-confirmed diagnosis point to a venous, not arterial, event.', 4),
('e0000000-0000-0000-0000-000000000008', 'E', 'Cerebral venous sinus thrombosis', true, 'Correct. A postural headache, papilloedema, focal seizures, and a postpartum hypercoagulable state are characteristic of cerebral venous sinus thrombosis, confirmed on MRI venography.', 5),
('e0000000-0000-0000-0000-000000000009', 'A', 'Cluster headache', false, 'Ruled out because cluster headache causes episodic unilateral pain with autonomic features but does not cause a delayed contralateral hemiparesis or relate to neck trauma.', 1),
('e0000000-0000-0000-0000-000000000009', 'B', $x$Bell's palsy$x$, false, $x$Ruled out because Bell's palsy causes lower motor neuron facial weakness, not isolated ptosis/miosis (Horner syndrome), and does not explain the subsequent contralateral hemiparesis.$x$, 2),
('e0000000-0000-0000-0000-000000000009', 'C', 'Migraine with brainstem aura', false, 'Ruled out because this does not explain the neck pain following trauma, the Horner syndrome, or the delayed unilateral hemiparesis from a vascular territory.', 3),
('e0000000-0000-0000-0000-000000000009', 'D', 'Temporal arteritis', false, 'Ruled out because temporal arteritis typically occurs in older patients with jaw claudication and scalp tenderness, not in a young patient following neck hyperextension.', 4),
('e0000000-0000-0000-0000-000000000009', 'E', 'Carotid artery dissection', true, 'Correct. Neck pain following mechanical neck trauma/hyperextension, an ipsilateral partial Horner syndrome (ptosis and miosis, without anhidrosis as sympathetic fibres to the face travel with the external carotid), and delayed contralateral stroke symptoms are classic for internal carotid artery dissection.', 5),
('e0000000-0000-0000-0000-000000000010', 'A', 'Loss of consciousness', false, 'Ruled out because loss of consciousness occurs in both syncope and seizures and does not discriminate between them.', 1),
('e0000000-0000-0000-0000-000000000010', 'B', 'Prolonged postictal confusion', true, 'Correct. A prolonged (>5 minute) period of confusion and drowsiness after the event is highly specific for an epileptic seizure; syncope is typically followed by rapid, full recovery of orientation within seconds to a couple of minutes.', 2),
('e0000000-0000-0000-0000-000000000010', 'C', 'Limb jerking', false, 'Ruled out because brief myoclonic jerks (convulsive syncope) can also occur with syncope due to transient cerebral hypoperfusion, so jerking alone is not the most specific discriminator.', 3),
('e0000000-0000-0000-0000-000000000010', 'D', 'Urinary incontinence', false, 'Ruled out because incontinence can occur in both seizures and syncope and is not a reliable discriminator on its own.', 4),
('e0000000-0000-0000-0000-000000000010', 'E', 'Lateral tongue biting alone', false, 'Ruled out because although lateral tongue biting is fairly specific for seizure, it is less sensitive and reliable as a standalone discriminator than the duration of postictal confusion.', 5),
('e0000000-0000-0000-0000-000000000011', 'A', 'Generalised absence seizure', false, 'Ruled out because absence seizures cause brief (seconds), abrupt blank staring episodes without aura, automatisms, or postictal confusion, unlike this prolonged, complex event.', 1),
('e0000000-0000-0000-0000-000000000011', 'B', 'Focal seizure with impaired awareness', true, 'Correct. An epigastric rising aura, deja vu, oral and manual automatisms (lip-smacking, fumbling), and impaired but not fully lost awareness with subsequent amnesia are classic for a focal seizure arising from the temporal lobe.', 2),
('e0000000-0000-0000-0000-000000000011', 'C', 'Primary generalised tonic-clonic seizure', false, 'Ruled out because there is no described loss of consciousness with convulsive motor activity; the automatisms and preserved partial responsiveness point to a focal, not generalised, seizure.', 3),
('e0000000-0000-0000-0000-000000000011', 'D', 'Myoclonic seizure', false, 'Ruled out because myoclonic seizures cause brief, shock-like jerks without the aura, automatisms or altered awareness described.', 4),
('e0000000-0000-0000-0000-000000000011', 'E', 'Atonic seizure ("drop attack")', false, 'Ruled out because atonic seizures cause sudden loss of muscle tone and falls, not the prolonged automatisms and rising epigastric aura described.', 5),
('e0000000-0000-0000-0000-000000000012', 'A', 'IV phenytoin loading dose immediately', false, 'Ruled out because second-line anticonvulsants like phenytoin are used if seizures continue despite two adequate doses of benzodiazepine; a further benzodiazepine dose via the now-available IV route is appropriate first.', 1),
('e0000000-0000-0000-0000-000000000012', 'B', 'IV lorazepam', true, 'Correct. With IV access now available and ongoing status epilepticus despite pre-hospital buccal midazolam, IV lorazepam is the next step, as it is the first-line benzodiazepine once IV access is obtained, with a further dose given if seizures persist after 5-10 minutes.', 2),
('e0000000-0000-0000-0000-000000000012', 'C', 'Rapid sequence induction and general anaesthesia', false, 'Ruled out because this is reserved for refractory status epilepticus that continues despite first- and second-line anticonvulsant therapy, not as an immediate next step.', 3),
('e0000000-0000-0000-0000-000000000012', 'D', 'Oral sodium valproate', false, 'Ruled out because oral medication cannot be safely given to a convulsing patient and has too slow an onset for acute seizure termination.', 4),
('e0000000-0000-0000-0000-000000000012', 'E', 'Observation only, as most seizures self-terminate', false, 'Ruled out because this seizure has already continued for 15 minutes, meeting the definition of status epilepticus, which requires active treatment given the risks of ongoing cerebral injury.', 5),
('e0000000-0000-0000-0000-000000000013', 'A', 'Absence epilepsy', false, 'Ruled out because absence epilepsy causes brief staring episodes without motor jerks, and typically presents in younger children with a 3 Hz spike-and-wave pattern, not the polyspike pattern and myoclonic jerks described.', 1),
('e0000000-0000-0000-0000-000000000013', 'B', 'West syndrome', false, 'Ruled out because West syndrome (infantile spasms) presents in infancy with clusters of flexor spasms and a hypsarrhythmia EEG pattern, not in an adolescent with isolated myoclonic jerks.', 2),
('e0000000-0000-0000-0000-000000000013', 'C', 'Juvenile myoclonic epilepsy', true, 'Correct. Early-morning myoclonic jerks, generalised tonic-clonic seizures, onset in adolescence, sensitivity to sleep deprivation and alcohol, and a generalised polyspike-and-wave EEG pattern are all characteristic of juvenile myoclonic epilepsy.', 3),
('e0000000-0000-0000-0000-000000000013', 'D', 'Lennox-Gastaut syndrome', false, 'Ruled out because this presents in early childhood with multiple seizure types, developmental delay, and a slow spike-and-wave EEG pattern, not this relatively benign adolescent-onset picture.', 4),
('e0000000-0000-0000-0000-000000000013', 'E', 'Temporal lobe epilepsy', false, 'Ruled out because temporal lobe epilepsy typically causes focal seizures with auras and automatisms, not the symmetric early-morning myoclonic jerks and generalised EEG changes described.', 5),
('e0000000-0000-0000-0000-000000000014', 'A', 'Focal seizure with impaired awareness', false, 'Ruled out because focal seizures are typically longer, associated with automatisms and postictal confusion, and show focal (not generalised 3 Hz) EEG changes.', 1),
('e0000000-0000-0000-0000-000000000014', 'B', 'Attention deficit hyperactivity disorder', false, 'Ruled out because ADHD does not cause abrupt, stereotyped episodes with an EEG correlate; the described pattern with 3 Hz spike-wave discharges is diagnostic of a seizure disorder.', 2),
('e0000000-0000-0000-0000-000000000014', 'C', 'Juvenile myoclonic epilepsy', false, 'Ruled out because JME causes myoclonic jerks and typically presents in adolescence with polyspike-wave, not this childhood-onset staring pattern with classic 3 Hz spike-wave.', 3),
('e0000000-0000-0000-0000-000000000014', 'D', 'Childhood absence epilepsy', true, 'Correct. Brief (seconds), frequent staring episodes with abrupt onset and offset, no postictal confusion, eyelid fluttering, provocation by hyperventilation, and a 3 Hz generalised spike-and-wave EEG pattern are classic for childhood absence epilepsy.', 4),
('e0000000-0000-0000-0000-000000000014', 'E', 'Daydreaming (normal behaviour)', false, 'Ruled out because the abrupt onset/offset, frequency (up to 20 times daily), and confirmatory EEG findings distinguish this from normal inattention.', 5),
('e0000000-0000-0000-0000-000000000015', 'A', 'He must stop driving and cannot reapply for a licence', false, 'Ruled out because a single unprovoked seizure with normal investigations does not result in permanent driving prohibition under DVLA rules.', 1),
('e0000000-0000-0000-0000-000000000015', 'B', 'He can continue driving as normal', false, 'Ruled out because any seizure, even a first one, requires cessation of driving and notification of the DVLA; he cannot continue driving unrestricted.', 2),
('e0000000-0000-0000-0000-000000000015', 'C', 'He must stop driving for 12 months regardless of investigation results', false, 'Ruled out because the 12-month rule applies to those with an established diagnosis of epilepsy (recurrent seizures) or abnormal investigations, not necessarily a single seizure with normal MRI/EEG.', 3),
('e0000000-0000-0000-0000-000000000015', 'D', 'Only Group 2 (HGV/PCV) licence holders need to stop driving after a first seizure', false, 'Ruled out because Group 1 licence holders are also required to stop driving and inform the DVLA after any seizure; Group 2 rules are simply far stricter (typically a much longer seizure-free period).', 4),
('e0000000-0000-0000-0000-000000000015', 'E', 'He must stop driving and inform the DVLA; he may reapply after 6 months if seizure-free', true, 'Correct. For a first unprovoked seizure with a normal brain scan and EEG, DVLA rules require the patient to stop driving a Group 1 vehicle and notify the DVLA; he may be considered for relicensing after 6 months provided he remains seizure-free.', 5),
('e0000000-0000-0000-0000-000000000016', 'A', 'Continue sodium valproate unchanged as it is working well', false, 'Ruled out because sodium valproate carries a high risk of major congenital malformations and neurodevelopmental problems, and its use in women of childbearing potential is now tightly restricted; it should not simply be continued unchanged.', 1),
('e0000000-0000-0000-0000-000000000016', 'B', 'Stop all antiepileptic medication before conception', false, 'Ruled out because abruptly stopping treatment risks uncontrolled seizures, which themselves pose serious risks to mother and fetus (including status epilepticus); therapy should be optimised, not withdrawn, before pregnancy.', 2),
('e0000000-0000-0000-0000-000000000016', 'C', 'Add high-dose folic acid and continue valproate without further review', false, $x$Ruled out because folic acid reduces neural tube defect risk generally but does not mitigate valproate's specific teratogenic and neurodevelopmental risks; a medication review is still required.$x$, 3),
('e0000000-0000-0000-0000-000000000016', 'D', 'Refer for pre-conception counselling to switch to a lower-risk antiepileptic', true, 'Correct. Sodium valproate is teratogenic and associated with neurodevelopmental disorders; current guidance is that it should be avoided in women who could become pregnant unless no other effective treatment is available, so pre-conception counselling to consider switching to a lower-risk agent (e.g. lamotrigine or levetiracetam) is appropriate.', 4),
('e0000000-0000-0000-0000-000000000016', 'E', 'Delay any changes until she is already pregnant', false, 'Ruled out because antiepileptic changes are ideally made before conception, when possible, to establish a stable regimen and avoid switching drugs during early pregnancy when the fetus is most vulnerable.', 5),
('e0000000-0000-0000-0000-000000000017', 'A', $x$Todd's paresis$x$, true, $x$Correct. Transient focal weakness following a focal seizure, in the same distribution as the seizure activity, that resolves spontaneously over hours without a new structural lesion on imaging, is Todd's paresis (postictal paralysis).$x$, 1),
('e0000000-0000-0000-0000-000000000017', 'B', 'New ischaemic stroke', false, 'Ruled out because a normal CT and gradual, complete resolution of the deficit over hours is inconsistent with a new structural stroke, which would not spontaneously and fully resolve so quickly.', 2),
('e0000000-0000-0000-0000-000000000017', 'C', 'Guillain-Barre syndrome', false, 'Ruled out because GBS causes a progressive, ascending, symmetric weakness over days, unrelated temporally to a seizure, and would not resolve within 12 hours.', 3),
('e0000000-0000-0000-0000-000000000017', 'D', 'Transient ischaemic attack', false, 'Ruled out because the temporal relationship to the seizure and the pattern of gradual resolution over many hours is more consistent with a postictal phenomenon than a separate vascular event.', 4),
('e0000000-0000-0000-0000-000000000017', 'E', 'Conversion disorder', false, 'Ruled out because the clear temporal association with a witnessed seizure and typical gradual resolution make a physiological postictal phenomenon far more likely than a functional/psychogenic cause.', 5),
('e0000000-0000-0000-0000-000000000018', 'A', 'Cluster headache', false, 'Ruled out because cluster headache causes severe unilateral periorbital pain with autonomic features (lacrimation, ptosis) in short, clustered attacks, without the slowly spreading visual aura described.', 1),
('e0000000-0000-0000-0000-000000000018', 'B', 'Transient ischaemic attack', false, 'Ruled out because visual symptoms in TIA are typically sudden in onset (not gradually spreading over 20 minutes) and are usually negative (loss of vision) rather than the positive, spreading phenomena (zigzags, flashing lights) described.', 2),
('e0000000-0000-0000-0000-000000000018', 'C', 'Tension-type headache', false, 'Ruled out because tension headache causes bilateral, band-like, non-throbbing pain without visual aura, nausea, or photophobia of this severity.', 3),
('e0000000-0000-0000-0000-000000000018', 'D', 'Occipital lobe seizure', false, 'Ruled out because seizure-related visual phenomena are typically brief (seconds) and stereotyped flashes, not a slowly evolving, spreading aura lasting up to 20-30 minutes.', 4),
('e0000000-0000-0000-0000-000000000018', 'E', 'Migraine with aura', true, 'Correct. A gradually spreading, positive visual aura (zigzag lines, flashing lights) evolving over minutes, followed by a unilateral throbbing headache with nausea and photophobia, and complete resolution between episodes, is classic for migraine with aura.', 5),
('e0000000-0000-0000-0000-000000000019', 'A', 'Cluster headache', true, 'Correct. Severe, strictly unilateral periorbital pain in discrete attacks lasting 15-180 minutes, with ipsilateral autonomic features (lacrimation, nasal congestion) and restlessness/agitation during attacks, occurring in clusters, is characteristic of cluster headache.', 1),
('e0000000-0000-0000-0000-000000000019', 'B', 'Migraine without aura', false, 'Ruled out because migraine sufferers typically prefer to lie still in a dark room rather than pace restlessly, and migraine attacks last much longer (4-72 hours) than the 45-minute episodes described.', 2),
('e0000000-0000-0000-0000-000000000019', 'C', 'Trigeminal neuralgia', false, 'Ruled out because trigeminal neuralgia causes brief, electric shock-like facial pains lasting seconds, triggered by touch or chewing, not prolonged attacks with autonomic features.', 3),
('e0000000-0000-0000-0000-000000000019', 'D', 'Giant cell arteritis', false, 'Ruled out because GCA typically occurs in older patients with a constant, not episodic, headache, often with scalp tenderness and jaw claudication, and would not present as discrete nightly attacks in a young man.', 4),
('e0000000-0000-0000-0000-000000000019', 'E', 'Sinusitis', false, 'Ruled out because sinusitis causes a more constant facial pressure/pain with other features of infection, not brief, severe, recurring episodic attacks with the restless behaviour described.', 5),
('e0000000-0000-0000-0000-000000000020', 'A', 'Tension-type headache', true, 'Correct. Bilateral, non-throbbing, band-like or pressure-type pain of mild-to-moderate intensity, without nausea, photophobia, or aggravation by routine physical activity, and a normal examination, is characteristic of tension-type headache.', 1),
('e0000000-0000-0000-0000-000000000020', 'B', 'Migraine without aura', false, 'Ruled out because migraine typically causes unilateral, throbbing pain aggravated by activity, often with nausea and photophobia, features absent here.', 2),
('e0000000-0000-0000-0000-000000000020', 'C', 'Medication overuse headache', false, 'Ruled out because there is no history given of frequent analgesic use; this diagnosis requires a history of regular acute headache medication use, which is not described.', 3),
('e0000000-0000-0000-0000-000000000020', 'D', 'Raised intracranial pressure', false, 'Ruled out because raised ICP headache is typically worse in the morning, worse on lying flat, or associated with vomiting or papilloedema, none of which are described, and this presentation is chronic and non-progressive.', 4),
('e0000000-0000-0000-0000-000000000020', 'E', 'Trigeminal neuralgia', false, 'Ruled out because trigeminal neuralgia causes brief, severe, unilateral electric shock-like pain in a trigeminal distribution, not a bilateral, dull, constant pressure sensation.', 5),
('e0000000-0000-0000-0000-000000000021', 'A', 'Cluster headache', false, 'Ruled out because cluster headache causes prolonged (15-180 minute) attacks with autonomic features, not the brief (seconds), trigger-provoked pain described here.', 1),
('e0000000-0000-0000-0000-000000000021', 'B', 'Temporomandibular joint dysfunction', false, 'Ruled out because TMJ dysfunction typically causes a dull ache localised to the jaw joint, worsened by chewing, without the electric shock-like quality or light-touch triggers described.', 2),
('e0000000-0000-0000-0000-000000000021', 'C', 'Postherpetic neuralgia', false, 'Ruled out because there is no history of a preceding vesicular rash (shingles) in a trigeminal distribution, which would be expected before postherpetic neuralgia develops.', 3),
('e0000000-0000-0000-0000-000000000021', 'D', 'Trigeminal neuralgia', true, 'Correct. Brief, severe, electric shock-like unilateral facial pain, triggered by innocuous stimuli (touch, chewing, wind), with a pain-free interval between attacks and a normal neurological examination, is classic for trigeminal neuralgia.', 4),
('e0000000-0000-0000-0000-000000000021', 'E', 'Giant cell arteritis', false, 'Ruled out because GCA causes a more constant headache/scalp tenderness with systemic features, not brief, trigger-provoked, electric shock-like pain with a normal examination.', 5),
('e0000000-0000-0000-0000-000000000022', 'A', 'Arrange temporal artery biopsy and await results before starting treatment', false, 'Ruled out because delaying steroid treatment pending biopsy risks sudden, irreversible visual loss from anterior ischaemic optic neuropathy; treatment should not be withheld while awaiting confirmation.', 1),
('e0000000-0000-0000-0000-000000000022', 'B', 'Prescribe simple analgesia and review in two weeks', false, 'Ruled out because this presentation carries a high risk of imminent, irreversible blindness if untreated; urgent steroid treatment, not simple analgesia and delayed review, is required.', 2),
('e0000000-0000-0000-0000-000000000022', 'C', 'Start triptan therapy for suspected migraine', false, 'Ruled out because the age of onset, jaw claudication, raised inflammatory markers, and associated girdle stiffness make GCA far more likely than migraine, and triptans do not address the underlying vasculitis.', 3),
('e0000000-0000-0000-0000-000000000022', 'D', 'Start high-dose oral prednisolone immediately and arrange urgent temporal artery biopsy', true, 'Correct. This presentation (new temporal headache, scalp tenderness, jaw claudication, markedly raised ESR, associated polymyalgic symptoms) is classic for giant cell arteritis; treatment with high-dose glucocorticoids should start immediately, without waiting for biopsy, to prevent irreversible visual loss, with biopsy arranged urgently to confirm the diagnosis.', 4),
('e0000000-0000-0000-0000-000000000022', 'E', 'Arrange outpatient MRI brain before any treatment', false, 'Ruled out because MRI is not the diagnostic test of choice for GCA (temporal artery biopsy is) and, more importantly, treatment must not be delayed while awaiting any imaging given the risk of sudden vision loss.', 5),
('e0000000-0000-0000-0000-000000000023', 'A', 'Bacterial meningitis', false, 'Ruled out because there is no fever, neck stiffness, or CSF pleocytosis/abnormal biochemistry to suggest infection; CSF constituents are normal here.', 1),
('e0000000-0000-0000-0000-000000000023', 'B', 'Cerebral venous sinus thrombosis', false, 'Ruled out because this would typically be identified on MRI venography, and while it can mimic IIH, the normal MRI here points to a primary (idiopathic) process rather than a structural venous cause.', 2),
('e0000000-0000-0000-0000-000000000023', 'C', 'Migraine with aura', false, 'Ruled out because migraine does not cause papilloedema or a persistently raised CSF opening pressure.', 3),
('e0000000-0000-0000-0000-000000000023', 'D', 'Idiopathic intracranial hypertension', true, 'Correct. Headache worse on lying flat, papilloedema, pulsatile tinnitus and visual disturbance, in an obese woman of reproductive age, with a normal MRI (excluding a mass lesion) and a raised CSF opening pressure with normal CSF composition, is diagnostic of idiopathic intracranial hypertension.', 4),
('e0000000-0000-0000-0000-000000000023', 'E', 'Normal pressure hydrocephalus', false, 'Ruled out because NPH classically presents in older patients with the triad of gait disturbance, urinary incontinence and cognitive decline, with normal (not raised) CSF opening pressure.', 5),
('e0000000-0000-0000-0000-000000000024', 'A', 'Anti-voltage-gated calcium channel antibody', false, 'Ruled out because this antibody is associated with Lambert-Eaton myasthenic syndrome, which characteristically improves (rather than worsens) with sustained muscle use and is often paraneoplastic.', 1),
('e0000000-0000-0000-0000-000000000024', 'B', 'Anti-GQ1b antibody', false, 'Ruled out because this antibody is associated with Miller Fisher syndrome (ataxia, areflexia, ophthalmoplegia), not the fatigable weakness pattern described here.', 2),
('e0000000-0000-0000-0000-000000000024', 'C', 'Anti-MuSK antibody', false, 'Ruled out because although anti-MuSK is a cause of myasthenia gravis, it is far less common than anti-AChR and typically causes more prominent bulbar/facial weakness; anti-AChR remains the most likely single answer given the classic presentation.', 3),
('e0000000-0000-0000-0000-000000000024', 'D', 'Anti-acetylcholine receptor antibody', true, 'Correct. Fatigable ptosis and diplopia worsening with sustained use and improving with rest, plus bulbar fatigue (chewing), is classic myasthenia gravis, most commonly associated with anti-acetylcholine receptor (anti-AChR) antibodies.', 4),
('e0000000-0000-0000-0000-000000000024', 'E', 'Anti-Hu antibody', false, 'Ruled out because anti-Hu antibodies are associated with paraneoplastic sensory neuronopathy and encephalomyelitis, not the fatigable neuromuscular junction weakness described.', 5),
('e0000000-0000-0000-0000-000000000025', 'A', 'Myasthenia gravis', false, 'Ruled out because myasthenia gravis causes fatigable weakness that worsens, not improves, with sustained contraction, and typically causes prominent ocular/bulbar rather than proximal limb-predominant weakness with autonomic features.', 1),
('e0000000-0000-0000-0000-000000000025', 'B', 'Lambert-Eaton myasthenic syndrome', true, 'Correct. Proximal limb weakness, autonomic symptoms (dry mouth), initially reduced/absent reflexes that improve (post-tetanic potentiation) after sustained contraction, and association with small cell lung cancer, are classic for Lambert-Eaton myasthenic syndrome, a paraneoplastic disorder of presynaptic voltage-gated calcium channels.', 2),
('e0000000-0000-0000-0000-000000000025', 'C', 'Guillain-Barre syndrome', false, 'Ruled out because GBS causes an acute, progressive, symmetric ascending weakness typically following infection, not the chronic proximal weakness with post-tetanic facilitation described, and is not classically paraneoplastic.', 3),
('e0000000-0000-0000-0000-000000000025', 'D', 'Polymyositis', false, 'Ruled out because polymyositis causes proximal weakness but with normal or reduced (not initially absent, improving) reflexes, no autonomic features, and would present with a raised creatine kinase rather than the described reflex pattern.', 4),
('e0000000-0000-0000-0000-000000000025', 'E', 'Motor neuron disease', false, 'Ruled out because MND causes a mix of upper and lower motor neuron signs without autonomic involvement or the characteristic reflex facilitation seen here, and would not fluctuate in this pattern.', 5),
('e0000000-0000-0000-0000-000000000026', 'A', 'Regular monitoring of forced vital capacity with early involvement of critical care', true, 'Correct. GBS can cause life-threatening respiratory failure from diaphragmatic and intercostal muscle weakness; regular FVC monitoring to detect impending respiratory failure, with early critical care/anaesthetic involvement (alongside IVIG or plasma exchange as disease-modifying treatment), is the immediate priority given the falling FVC.', 1),
('e0000000-0000-0000-0000-000000000026', 'B', 'Start oral corticosteroids', false, 'Ruled out because corticosteroids have not been shown to be effective in Guillain-Barre syndrome and are not part of standard management.', 2),
('e0000000-0000-0000-0000-000000000026', 'C', 'Reassure and review in one week as an outpatient', false, 'Ruled out because progressive ascending weakness with falling respiratory function indicates a potentially life-threatening, rapidly evolving illness requiring inpatient monitoring, not outpatient review.', 3),
('e0000000-0000-0000-0000-000000000026', 'D', 'Start long-term oral immunosuppression with azathioprine', false, 'Ruled out because azathioprine is not an effective acute treatment for GBS; IVIG or plasma exchange are the evidence-based acute therapies.', 4),
('e0000000-0000-0000-0000-000000000026', 'E', 'Lumbar puncture alone with no further action pending results', false, 'Ruled out because while LP (showing albuminocytological dissociation) supports the diagnosis, the immediate priority in a patient with falling FVC is close monitoring for respiratory failure, not simply awaiting a diagnostic test result.', 5),
('e0000000-0000-0000-0000-000000000027', 'A', 'Cervical radiculopathy', false, 'Ruled out because radiculopathy typically causes a dermatomal sensory disturbance alongside motor signs, and would not produce both lower motor neuron (wasting, fasciculations) and upper motor neuron (brisk reflexes, extensor plantar) signs in the same limb.', 1),
('e0000000-0000-0000-0000-000000000027', 'B', 'Peripheral neuropathy', false, 'Ruled out because peripheral neuropathy causes lower motor neuron signs with reduced (not brisk) reflexes and is usually accompanied by sensory symptoms, neither of which fits this purely motor, mixed UMN/LMN picture.', 2),
('e0000000-0000-0000-0000-000000000027', 'C', 'Multiple sclerosis', false, 'Ruled out because MS typically produces upper motor neuron signs from central demyelination without wasting or fasciculations (lower motor neuron signs), and usually has some sensory or visual involvement.', 3),
('e0000000-0000-0000-0000-000000000027', 'D', 'Motor neuron disease', true, 'Correct. The combination of lower motor neuron signs (wasting, fasciculations) and upper motor neuron signs (brisk reflexes, extensor plantar response) in the same limb or region, with no sensory involvement, is the classic hallmark of motor neuron disease (amyotrophic lateral sclerosis).', 4),
('e0000000-0000-0000-0000-000000000027', 'E', 'Cervical myelopathy', false, 'Ruled out because myelopathy typically causes upper motor neuron signs below the lesion but would not explain focal wasting and fasciculations confined to small hand muscles without a clear sensory level.', 5),
('e0000000-0000-0000-0000-000000000028', 'A', 'Carpal tunnel syndrome', true, $x$Correct. Nocturnal numbness and tingling in the median nerve distribution (thumb, index, middle finger, and radial half of the ring finger), relieved by shaking the hand ("flick sign"), with a positive Tinel's sign, is classic for carpal tunnel syndrome, which is more common in pregnancy due to fluid retention.$x$, 1),
('e0000000-0000-0000-0000-000000000028', 'B', 'Ulnar neuropathy', false, 'Ruled out because ulnar neuropathy causes sensory symptoms in the little finger and ulnar half of the ring finger, not the thumb, index and middle finger distribution described.', 2),
('e0000000-0000-0000-0000-000000000028', 'C', 'Cervical radiculopathy (C6)', false, 'Ruled out because although C6 radiculopathy can cause thumb and index finger symptoms, it would typically be associated with neck pain, a dermatomal pattern extending to the forearm, and would not be specifically reproduced by tapping the wrist.', 3),
('e0000000-0000-0000-0000-000000000028', 'D', 'Thoracic outlet syndrome', false, 'Ruled out because thoracic outlet syndrome typically causes symptoms in the ulnar distribution (C8-T1) with possible vascular signs in the arm, not this classic median nerve pattern.', 4),
('e0000000-0000-0000-0000-000000000028', 'E', 'Radial neuropathy', false, 'Ruled out because radial neuropathy causes weakness of wrist/finger extension (wrist drop) with sensory loss over the dorsum of the hand, not the palmar median distribution described.', 5),
('e0000000-0000-0000-0000-000000000029', 'A', 'Guillain-Barre syndrome', false, 'Ruled out because GBS is an acute, monophasic, typically post-infectious illness evolving over days to weeks, not a lifelong, slowly progressive, familial condition.', 1),
('e0000000-0000-0000-0000-000000000029', 'B', 'Diabetic peripheral neuropathy', false, 'Ruled out because there is no history of diabetes, and the lifelong duration, family history, and skeletal deformity (pes cavus) point to a hereditary rather than metabolic cause.', 2),
('e0000000-0000-0000-0000-000000000029', 'C', 'Charcot-Marie-Tooth disease', true, 'Correct. A hereditary (autosomal dominant, family history present), slowly progressive distal sensorimotor peripheral neuropathy causing pes cavus, distal leg wasting ("inverted champagne bottle" legs), absent ankle reflexes, and stocking-distribution sensory loss, with onset from childhood/adolescence, is classic for Charcot-Marie-Tooth disease.', 3),
('e0000000-0000-0000-0000-000000000029', 'D', 'Multiple sclerosis', false, 'Ruled out because MS is a central demyelinating disease causing upper motor neuron signs and would not cause absent reflexes, pes cavus, or a hereditary pattern.', 4),
('e0000000-0000-0000-0000-000000000029', 'E', 'Vitamin B12 deficiency', false, 'Ruled out because B12 deficiency causes a subacute combined degeneration with both peripheral neuropathy and posterior column/corticospinal signs, typically in an older patient, not a lifelong familial condition with skeletal deformity from childhood.', 5),
('e0000000-0000-0000-0000-000000000030', 'A', 'Guillain-Barre syndrome', false, 'Ruled out because GBS causes an acute, progressive, predominantly motor weakness over days to weeks, not a chronic, sensory-predominant, symmetric neuropathy developing over years.', 1),
('e0000000-0000-0000-0000-000000000030', 'B', 'Multiple sclerosis', false, 'Ruled out because MS is a central demyelinating disease and would not cause this length-dependent stocking-distribution sensory loss with absent reflexes, which reflects a peripheral, not central, process.', 2),
('e0000000-0000-0000-0000-000000000030', 'C', 'Diabetic peripheral neuropathy', true, 'Correct. A symmetric, distal, sensory-predominant polyneuropathy in a "stocking" distribution, with reduced vibration sense and absent ankle reflexes but preserved power, in a patient with longstanding poorly controlled diabetes, is the classic presentation of diabetic peripheral neuropathy.', 3),
('e0000000-0000-0000-0000-000000000030', 'D', 'Vitamin B12 deficiency', false, 'Ruled out because although B12 deficiency also causes peripheral neuropathy, it typically also produces upper motor neuron signs (subacute combined degeneration) and would not be the most likely diagnosis given the strong contextual history of longstanding diabetes.', 4),
('e0000000-0000-0000-0000-000000000030', 'E', 'Charcot-Marie-Tooth disease', false, 'Ruled out because CMT is a hereditary condition presenting from childhood with skeletal deformity (pes cavus), not an acquired, adult-onset neuropathy clearly linked to longstanding diabetes.', 5),
('e0000000-0000-0000-0000-000000000031', 'A', 'Unilateral facial weakness', false, $x$Ruled out because unilateral facial weakness occurs in both upper motor neuron (stroke) and lower motor neuron (Bell's palsy) lesions and does not by itself discriminate between them.$x$, 1),
('e0000000-0000-0000-0000-000000000031', 'B', 'Inability to raise the eyebrow on the affected side', true, $x$Correct. The forehead receives bilateral upper motor neuron innervation, so a cortical (upper motor neuron) stroke spares the forehead, allowing the patient to still raise their eyebrow; inability to raise the eyebrow indicates a lower motor neuron lesion affecting the whole side of the face, as in Bell's palsy.$x$, 2),
('e0000000-0000-0000-0000-000000000031', 'C', 'Drooping of the mouth corner', false, $x$Ruled out because drooping of the lower face occurs in both stroke (upper motor neuron) and Bell's palsy (lower motor neuron) facial weakness and does not discriminate between them.$x$, 3),
('e0000000-0000-0000-0000-000000000031', 'D', 'Sudden onset', false, $x$Ruled out because both Bell's palsy and stroke can present with sudden onset of facial weakness; onset speed alone does not reliably distinguish the two.$x$, 4),
('e0000000-0000-0000-0000-000000000031', 'E', 'Absence of limb weakness', false, 'Ruled out because while helpful in making stroke less likely, some strokes (e.g. small pontine infarcts) can cause isolated facial weakness without limb involvement, so this is a less specific discriminator than the pattern of forehead involvement.', 5),
('e0000000-0000-0000-0000-000000000032', 'A', 'Ulnar nerve palsy', false, 'Ruled out because ulnar neuropathy causes weakness of finger abduction/adduction and a claw hand, with sensory loss over the little finger, not wrist drop or dorsal web space numbness.', 1),
('e0000000-0000-0000-0000-000000000032', 'B', 'Radial nerve palsy', true, 'Correct. Wrist and finger drop with sensory loss confined to the dorsal first web space, following prolonged compression of the arm (classically against a hard surface, "Saturday night palsy"), with preserved triceps and elbow flexion, is characteristic of a radial nerve palsy at the spiral groove.', 2),
('e0000000-0000-0000-0000-000000000032', 'C', 'Median nerve palsy', false, 'Ruled out because median neuropathy causes weakness of thumb opposition and sensory loss over the palmar radial three and a half fingers, not wrist extension weakness or dorsal sensory loss.', 3),
('e0000000-0000-0000-0000-000000000032', 'D', 'C7 radiculopathy', false, 'Ruled out because although C7 lesions can cause finger extension weakness, they would typically also affect triceps power (weak elbow extension) and cause a dermatomal (not purely radial nerve) sensory pattern, and would not be linked to a clear compressive history.', 4),
('e0000000-0000-0000-0000-000000000032', 'E', 'Brachial plexus injury', false, 'Ruled out because a plexus injury would typically cause a more widespread pattern of weakness across multiple nerve distributions, not this isolated, clearly compressive mononeuropathy sparing triceps and elbow flexion.', 5),
('e0000000-0000-0000-0000-000000000033', 'A', 'Essential tremor', false, 'Ruled out because essential tremor is typically a bilateral action/postural tremor that worsens with movement and improves at rest, the opposite pattern to the resting tremor described here.', 1),
('e0000000-0000-0000-0000-000000000033', 'B', 'Drug-induced parkinsonism', false, $x$Ruled out because there is no history given of a causative medication (e.g. antipsychotics, metoclopramide); idiopathic Parkinson's disease is more likely as the primary diagnosis in this context.$x$, 2),
('e0000000-0000-0000-0000-000000000033', 'C', $x$Parkinson's disease$x$, true, $x$Correct. Asymmetric resting tremor (improving with action), bradykinesia, cogwheel rigidity, and a shuffling, stooped gait are the classic clinical triad (plus gait change) of idiopathic Parkinson's disease.$x$, 3),
('e0000000-0000-0000-0000-000000000033', 'D', 'Progressive supranuclear palsy', false, 'Ruled out because PSP typically presents with early postural instability/falls and a characteristic vertical gaze palsy, features not described here, along with a poorer response to levodopa.', 4),
('e0000000-0000-0000-0000-000000000033', 'E', 'Normal pressure hydrocephalus', false, 'Ruled out because NPH causes a broad-based, magnetic gait with urinary incontinence and cognitive decline, rather than the asymmetric resting tremor and cogwheel rigidity described.', 5),
('e0000000-0000-0000-0000-000000000034', 'A', $x$Idiopathic Parkinson's disease$x$, false, 'Ruled out because idiopathic PD typically causes asymmetric limb-predominant signs with a good, sustained response to levodopa, and does not cause early falls or a vertical gaze palsy.', 1),
('e0000000-0000-0000-0000-000000000034', 'B', 'Multiple system atrophy', false, 'Ruled out because MSA is characterised more by early autonomic failure (postural hypotension, urinary dysfunction) and cerebellar or additional parkinsonian features, rather than the specific vertical gaze palsy described here.', 2),
('e0000000-0000-0000-0000-000000000034', 'C', 'Essential tremor', false, 'Ruled out because essential tremor does not cause falls, gaze palsy, or axial rigidity; it is an isolated action tremor without these additional features.', 3),
('e0000000-0000-0000-0000-000000000034', 'D', 'Corticobasal degeneration', false, 'Ruled out because corticobasal degeneration classically causes markedly asymmetric limb rigidity/apraxia with an "alien limb" phenomenon, rather than the prominent early falls and vertical gaze palsy described here.', 4),
('e0000000-0000-0000-0000-000000000034', 'E', 'Progressive supranuclear palsy', true, 'Correct. Early postural instability with backward falls, a supranuclear vertical gaze palsy (particularly impaired downgaze), axial rigidity, and a poor response to levodopa are characteristic features of progressive supranuclear palsy, a Parkinson-plus syndrome.', 5),
('e0000000-0000-0000-0000-000000000035', 'A', $x$Parkinson's disease$x$, false, $x$Ruled out because Parkinson's disease causes an asymmetric resting tremor that improves, not worsens, with action, along with bradykinesia and rigidity, none of which are present here.$x$, 1),
('e0000000-0000-0000-0000-000000000035', 'B', 'Physiological tremor', false, 'Ruled out because physiological tremor is typically fine, high-frequency, and only apparent under specific conditions (e.g. anxiety, thyrotoxicosis, caffeine), not a longstanding, familial tremor significant enough to affect writing and holding objects.', 2),
('e0000000-0000-0000-0000-000000000035', 'C', 'Cerebellar (intention) tremor', false, 'Ruled out because cerebellar tremor worsens as a target is approached (dysmetria) and is associated with other cerebellar signs (ataxia, dysdiadochokinesia), not simply a postural tremor without other cerebellar features.', 3),
('e0000000-0000-0000-0000-000000000035', 'D', 'Essential tremor', true, 'Correct. A bilateral postural/action tremor (worse with sustained posture or fine movement, better at complete rest), improved by alcohol, with a positive family history and no other parkinsonian features, is classic for essential tremor.', 4),
('e0000000-0000-0000-0000-000000000035', 'E', $x$Wilson's disease$x$, false, $x$Ruled out because Wilson's disease typically presents in a younger patient with additional features (liver disease, psychiatric symptoms, Kayser-Fleischer rings), not an isolated familial postural tremor in a woman of this age.$x$, 5),
('e0000000-0000-0000-0000-000000000036', 'A', $x$Parkinson's disease$x$, false, $x$Ruled out because Parkinson's disease causes bradykinesia, rigidity, and resting tremor (hypokinetic), the opposite pattern to the hyperkinetic chorea described here.$x$, 1),
('e0000000-0000-0000-0000-000000000036', 'B', $x$Wilson's disease$x$, false, $x$Ruled out because although Wilson's disease can cause movement disorders and psychiatric change, it typically presents at a younger age (teens to 30s) with liver disease and Kayser-Fleischer rings, and is autosomal recessive, not matching this family history pattern.$x$, 2),
('e0000000-0000-0000-0000-000000000036', 'C', $x$Sydenham's chorea$x$, false, $x$Ruled out because Sydenham's chorea occurs in children/young people following streptococcal infection (rheumatic fever) and is self-limiting, not a progressive adult-onset disorder with a strong family history.$x$, 3),
('e0000000-0000-0000-0000-000000000036', 'D', 'Tardive dyskinesia', false, 'Ruled out because there is no history of antipsychotic or dopamine-blocking medication use, which is required to cause tardive dyskinesia, and the strong autosomal dominant family history points to a genetic cause instead.', 4),
('e0000000-0000-0000-0000-000000000036', 'E', $x$Huntington's disease$x$, true, $x$Correct. Chorea (irregular, jerky, involuntary movements) combined with psychiatric/cognitive change (irritability, concentration difficulty) and a strong family history of a similar autosomal dominant condition with paternal transmission is classic for Huntington's disease, caused by a CAG trinucleotide repeat expansion.$x$, 5),
('e0000000-0000-0000-0000-000000000037', 'A', $x$Huntington's disease$x$, false, $x$Ruled out because Huntington's disease does not cause liver dysfunction or Kayser-Fleischer rings, and typically presents with chorea rather than this combined tremor/dysarthria/hepatic picture.$x$, 1),
('e0000000-0000-0000-0000-000000000037', 'B', $x$Parkinson's disease$x$, false, $x$Ruled out because Parkinson's disease typically presents in older adults and would not explain the deranged liver function or Kayser-Fleischer rings.$x$, 2),
('e0000000-0000-0000-0000-000000000037', 'C', $x$Wilson's disease$x$, true, $x$Correct. A young patient with a combined movement disorder (tremor, dysarthria), psychiatric/personality change, liver dysfunction, Kayser-Fleischer rings, and low serum caeruloplasmin has the classic multisystem presentation of Wilson's disease, an autosomal recessive disorder of copper metabolism causing copper accumulation in the liver, brain and cornea.$x$, 3),
('e0000000-0000-0000-0000-000000000037', 'D', 'Multiple sclerosis', false, $x$Ruled out because MS does not cause Kayser-Fleischer rings or liver dysfunction, and while it can cause dysarthria and tremor, the combination with low caeruloplasmin and corneal rings is specific to Wilson's disease.$x$, 4),
('e0000000-0000-0000-0000-000000000037', 'E', 'Alcoholic liver disease with hepatic encephalopathy', false, 'Ruled out because there is no history of alcohol excess given, and hepatic encephalopathy would not specifically cause Kayser-Fleischer rings or a low caeruloplasmin, which are specific markers of a copper metabolism disorder.', 5),
('e0000000-0000-0000-0000-000000000038', 'A', $x$Idiopathic Parkinson's disease$x$, false, 'Ruled out because idiopathic PD typically presents with asymmetric onset, whereas this patient has bilateral, symmetric symptoms developing in close temporal relationship to long-term antipsychotic (dopamine-blocking) therapy.', 1),
('e0000000-0000-0000-0000-000000000038', 'B', 'Progressive supranuclear palsy', false, 'Ruled out because PSP causes early falls and a vertical gaze palsy, neither of which is present here, and it is not linked to antipsychotic medication.', 2),
('e0000000-0000-0000-0000-000000000038', 'C', 'Drug-induced parkinsonism', true, 'Correct. Bilateral, symmetric parkinsonian features developing after starting a dopamine-blocking drug (such as a first-generation antipsychotic like haloperidol) is characteristic of drug-induced parkinsonism, caused by dopamine receptor blockade in the nigrostriatal pathway.', 3),
('e0000000-0000-0000-0000-000000000038', 'D', 'Multiple system atrophy', false, 'Ruled out because MSA is characterised by early autonomic failure and additional cerebellar features, not simply symmetric parkinsonism temporally linked to starting an antipsychotic.', 4),
('e0000000-0000-0000-0000-000000000038', 'E', 'Vascular parkinsonism', false, 'Ruled out because vascular parkinsonism typically affects the lower body predominantly ("lower body parkinsonism," gait apraxia) in a patient with vascular risk factors and imaging evidence of small vessel disease, not this clear temporal relationship to a dopamine-blocking drug.', 5),
('e0000000-0000-0000-0000-000000000039', 'A', 'Peripheral neuropathy', false, 'Ruled out because peripheral neuropathy typically causes a constant sensory disturbance (numbness, burning) that is not specifically relieved by movement or worsened by rest in this circadian pattern.', 1),
('e0000000-0000-0000-0000-000000000039', 'B', 'Nocturnal leg cramps', false, 'Ruled out because leg cramps are brief, painful, involuntary muscle contractions, not a persistent unpleasant sensation with an urge to move relieved by walking.', 2),
('e0000000-0000-0000-0000-000000000039', 'C', 'Restless legs syndrome', true, 'Correct. An unpleasant sensation in the legs with an urge to move them, worse at rest and in the evening/night, relieved by movement, is diagnostic of restless legs syndrome, which is associated with iron deficiency and chronic kidney disease.', 3),
('e0000000-0000-0000-0000-000000000039', 'D', 'Deep vein thrombosis', false, 'Ruled out because DVT causes unilateral leg swelling, pain and tenderness, not a bilateral, circadian, movement-relieved sensory urge.', 4),
('e0000000-0000-0000-0000-000000000039', 'E', 'Anxiety disorder', false, 'Ruled out because although restlessness can occur in anxiety, the specific circadian pattern (worse at rest/night), relief with movement, and association with iron deficiency/CKD are specific to restless legs syndrome, not a primary anxiety disorder.', 5),
('e0000000-0000-0000-0000-000000000040', 'A', 'Urgent CT head followed by lumbar puncture before any antibiotics', false, 'Ruled out because in suspected bacterial meningitis with a non-blanching rash suggesting meningococcal sepsis, antibiotics must not be delayed for investigations; delaying treatment significantly worsens outcome and mortality.', 1),
('e0000000-0000-0000-0000-000000000040', 'B', 'Oral antibiotics as an outpatient with review in 24 hours', false, 'Ruled out because this presentation represents a life-threatening emergency requiring immediate IV antibiotics and hospital admission, not oral treatment as an outpatient.', 2),
('e0000000-0000-0000-0000-000000000040', 'C', 'Immediate IV antibiotics (e.g. ceftriaxone) without waiting for investigations', true, 'Correct. Suspected bacterial meningitis with signs of meningococcal sepsis (non-blanching rash) is a medical emergency; IV antibiotics should be given immediately, before any imaging or lumbar puncture, to reduce the significant risk of death and neurological sequelae from delay.', 3),
('e0000000-0000-0000-0000-000000000040', 'D', 'Lumbar puncture first to confirm the diagnosis before starting treatment', false, 'Ruled out because performing LP before antibiotics unnecessarily delays life-saving treatment, and LP may in any case need to be deferred given the reduced consciousness (risk of coning).', 4),
('e0000000-0000-0000-0000-000000000040', 'E', 'Await blood culture results before starting antibiotics', false, 'Ruled out because waiting for culture results before treating suspected bacterial meningitis with sepsis significantly increases mortality; empirical treatment must start immediately on clinical suspicion.', 5),
('e0000000-0000-0000-0000-000000000041', 'A', 'Start empirical IV aciclovir immediately, without waiting for CSF PCR results', true, 'Correct. Fever, personality change/confusion, seizures and temporal lobe abnormality on MRI are highly suggestive of herpes simplex encephalitis, a treatable but rapidly progressive and potentially fatal condition; empirical IV aciclovir should be started immediately on clinical suspicion, without waiting for confirmatory PCR results.', 1),
('e0000000-0000-0000-0000-000000000041', 'B', 'Wait for CSF PCR results before starting any treatment', false, 'Ruled out because delaying aciclovir while awaiting PCR results significantly worsens outcomes in HSV encephalitis, which has high mortality and morbidity if treatment is delayed.', 2),
('e0000000-0000-0000-0000-000000000041', 'C', 'Start broad-spectrum antibiotics alone, without antiviral cover', false, 'Ruled out because the clinical and radiological picture (temporal lobe changes, personality change, seizures) is strongly suggestive of viral (HSV) encephalitis, which requires specific antiviral (not just antibacterial) cover.', 3),
('e0000000-0000-0000-0000-000000000041', 'D', 'Start high-dose corticosteroids alone', false, 'Ruled out because corticosteroids are not first-line treatment for HSV encephalitis; aciclovir is the essential, time-critical treatment, and steroids are not a substitute for it.', 4),
('e0000000-0000-0000-0000-000000000041', 'E', 'Discharge with oral antivirals and outpatient follow-up', false, 'Ruled out because this presentation represents a neurological emergency requiring inpatient IV treatment and close monitoring, not outpatient oral therapy.', 5),
('e0000000-0000-0000-0000-000000000042', 'A', 'Arrange urgent hospital transfer without giving any treatment beforehand', false, 'Ruled out because delaying antibiotics until hospital arrival, when transfer will take 40 minutes, significantly increases the risk of death from meningococcal sepsis; pre-hospital treatment is indicated.', 1),
('e0000000-0000-0000-0000-000000000042', 'B', 'Give oral amoxicillin and review the next day', false, 'Ruled out because this represents a rapidly progressive, life-threatening emergency requiring urgent parenteral antibiotics and same-day hospital transfer, not oral treatment with delayed review.', 2),
('e0000000-0000-0000-0000-000000000042', 'C', 'Withhold antibiotics until a firm diagnosis is confirmed in hospital', false, 'Ruled out because withholding treatment for a confirmatory test in a child with signs of meningococcal sepsis and a long transfer time significantly increases mortality risk.', 3),
('e0000000-0000-0000-0000-000000000042', 'D', 'Apply pressure to the rash and observe for 30 minutes', false, 'Ruled out because a non-blanching rash with fever and lethargy in a child is a medical emergency requiring immediate antibiotics and transfer, not observation.', 4),
('e0000000-0000-0000-0000-000000000042', 'E', 'Give IM or IV benzylpenicillin immediately, then arrange urgent hospital transfer', true, 'Correct. In suspected meningococcal disease with a non-blanching rash, a single dose of benzylpenicillin (IM or IV) should be given in primary care before transfer to hospital, unless there is a clear history of severe allergy, given the high mortality of delayed treatment.', 5),
('e0000000-0000-0000-0000-000000000043', 'A', 'Glioblastoma multiforme', false, 'Ruled out because although GBM also causes a ring-enhancing lesion, the presence of fever and a clear predisposing infective source (chronic otitis media) makes an infective abscess far more likely than a primary brain tumour in this context.', 1),
('e0000000-0000-0000-0000-000000000043', 'B', 'Brain abscess', true, 'Correct. A ring-enhancing lesion with surrounding oedema, fever, headache and a focal neurological deficit, in a patient with a contiguous source of infection (chronic otitis media, which can spread directly to the adjacent temporal lobe), is classic for a brain abscess.', 2),
('e0000000-0000-0000-0000-000000000043', 'C', 'Cerebral toxoplasmosis', false, 'Ruled out because toxoplasmosis typically occurs in immunocompromised patients (e.g. advanced HIV), which is not mentioned here, and would not be specifically linked to chronic otitis media.', 3),
('e0000000-0000-0000-0000-000000000043', 'D', 'Ischaemic stroke', false, 'Ruled out because stroke does not typically cause a ring-enhancing lesion on MRI, nor would it explain the fever and two-week subacute progression described.', 4),
('e0000000-0000-0000-0000-000000000043', 'E', 'Subdural empyema', false, 'Ruled out because subdural empyema is a collection over the brain surface (crescent-shaped, following the dural contour) rather than a discrete intraparenchymal ring-enhancing lesion, though it can arise from similar contiguous spread.', 5),
('e0000000-0000-0000-0000-000000000044', 'A', 'Acute bacterial meningitis', false, 'Ruled out because bacterial meningitis typically presents acutely (over hours) with a neutrophilic (not lymphocytic) CSF pleocytosis, unlike the subacute lymphocytic picture described here.', 1),
('e0000000-0000-0000-0000-000000000044', 'B', 'Viral meningitis', false, 'Ruled out because viral meningitis also causes a lymphocytic CSF pleocytosis but typically has a normal (not markedly reduced) CSF glucose and a more acute, self-limiting course, unlike the low glucose and subacute weight loss described here.', 2),
('e0000000-0000-0000-0000-000000000044', 'C', 'Cryptococcal meningitis', false, 'Ruled out because although cryptococcal meningitis can present subacutely with lymphocytic pleocytosis and low glucose, it typically occurs in immunocompromised (e.g. advanced HIV) patients, which is not specified here, whereas the TB risk factor (high-prevalence country) is explicitly given.', 3),
('e0000000-0000-0000-0000-000000000044', 'D', 'Tuberculous meningitis', true, 'Correct. A subacute (days to weeks, rather than hours) onset of fever, headache and confusion, in a patient from a high-TB-prevalence area, with CSF showing lymphocytic pleocytosis, markedly raised protein, and a low CSF:plasma glucose ratio, is classic for tuberculous meningitis.', 4),
('e0000000-0000-0000-0000-000000000044', 'E', 'Guillain-Barre syndrome', false, 'Ruled out because GBS causes a peripheral motor neuropathy with albuminocytological dissociation (raised protein, normal cell count) on CSF, not the lymphocytic pleocytosis with low glucose described, and does not cause confusion or fever.', 5),
('e0000000-0000-0000-0000-000000000045', 'A', 'Neuromyelitis optica', false, 'Ruled out because NMO typically causes more severe, often bilateral optic neuritis and longitudinally extensive spinal cord lesions (spanning three or more vertebral segments), a different pattern from the multiple, scattered, shorter lesions described here.', 1),
('e0000000-0000-0000-0000-000000000045', 'B', 'Single episode of optic neuritis (clinically isolated syndrome)', false, 'Ruled out because a second clinical episode (leg weakness) and further disseminated MRI findings have now occurred, meaning this is no longer an isolated single event but meets criteria for a diagnosis of MS.', 2),
('e0000000-0000-0000-0000-000000000045', 'C', 'Transverse myelitis alone', false, 'Ruled out because this term describes an isolated spinal cord inflammatory event, whereas this patient has two separate episodes (optic and spinal) with disseminated brain and cord lesions, consistent with a systemic demyelinating disease.', 3),
('e0000000-0000-0000-0000-000000000045', 'D', 'Vitamin B12 deficiency', false, 'Ruled out because B12 deficiency causes a symmetric subacute combined degeneration of the cord, not discrete, relapsing, disseminated demyelinating lesions with an initial episode of optic neuritis.', 4),
('e0000000-0000-0000-0000-000000000045', 'E', 'Multiple sclerosis', true, 'Correct. Two clinically distinct neurological episodes separated in time (optic neuritis, then leg weakness 18 months later) and MRI lesions disseminated in space (multiple locations) and time (some enhancing/active, some not), fulfils the criteria for a diagnosis of multiple sclerosis.', 5),
('e0000000-0000-0000-0000-000000000046', 'A', 'Optic neuritis', true, 'Correct. Subacute, painful (worse on eye movement) unilateral visual loss with reduced colour vision and a relative afferent pupillary defect (Marcus Gunn pupil) is classic for optic neuritis, commonly the first presentation of multiple sclerosis.', 1),
('e0000000-0000-0000-0000-000000000046', 'B', 'Central retinal artery occlusion', false, 'Ruled out because CRAO causes sudden, painless, profound visual loss due to acute retinal ischaemia, not the subacute, painful presentation with eye movement pain described here.', 2),
('e0000000-0000-0000-0000-000000000046', 'C', 'Anterior ischaemic optic neuropathy', false, 'Ruled out because AION typically causes sudden, painless visual loss in an older patient (often associated with giant cell arteritis), not the painful, subacute presentation in a young woman described here.', 3),
('e0000000-0000-0000-0000-000000000046', 'D', 'Retinal detachment', false, 'Ruled out because retinal detachment typically causes painless visual field loss described as a curtain or shadow, without pain on eye movement or the pupillary/colour vision findings described.', 4),
('e0000000-0000-0000-0000-000000000046', 'E', 'Migraine with visual aura', false, 'Ruled out because migrainous visual aura is transient (lasting minutes), fully reversible, and would not cause a persistent relative afferent pupillary defect or reduced colour vision.', 5),
('e0000000-0000-0000-0000-000000000047', 'A', 'Guillain-Barre syndrome', false, 'Ruled out because GBS causes an ascending peripheral neuropathy without a discrete sensory level or a spinal cord lesion on MRI, both of which are present here.', 1),
('e0000000-0000-0000-0000-000000000047', 'B', 'Cauda equina syndrome', false, 'Ruled out because cauda equina syndrome results from compression of lumbosacral nerve roots below the level of the spinal cord (conus), causing saddle anaesthesia and a different pattern of lower motor neuron signs, not a discrete thoracic cord lesion with a sensory level as described.', 2),
('e0000000-0000-0000-0000-000000000047', 'C', 'Transverse myelitis', true, 'Correct. Rapidly progressive bilateral leg weakness, a clear sensory level, and bladder dysfunction, with an inflammatory spinal cord lesion on MRI, is characteristic of transverse myelitis, an inflammatory demyelinating process affecting a segment of the spinal cord.', 3),
('e0000000-0000-0000-0000-000000000047', 'D', 'Spinal cord compression from disc herniation', false, 'Ruled out because there is no mechanical/structural cause described, and the MRI shows an inflammatory (not compressive) lesion, making transverse myelitis more likely.', 4),
('e0000000-0000-0000-0000-000000000047', 'E', 'Vitamin B12 deficiency (subacute combined degeneration)', false, 'Ruled out because SACD typically causes a more gradual, symmetric posterior column and corticospinal picture over weeks to months, not this acute, discrete inflammatory lesion with a clear sensory level over 48 hours.', 5),
('e0000000-0000-0000-0000-000000000048', 'A', 'Start a disease-modifying therapy such as natalizumab immediately', false, 'Ruled out because disease-modifying therapies are used for long-term relapse prevention, not to treat an acute relapse; they take weeks to become effective and do not hasten recovery from a current attack.', 1),
('e0000000-0000-0000-0000-000000000048', 'B', 'High-dose corticosteroids, e.g. IV methylprednisolone', true, 'Correct. A significant, functionally disabling acute relapse of MS (in the absence of infection, which must first be considered) is treated with a short course of high-dose corticosteroids (typically IV methylprednisolone) to hasten recovery, though this does not alter the long-term disease course.', 2),
('e0000000-0000-0000-0000-000000000048', 'C', 'Long-term oral prednisolone', false, 'Ruled out because long-term oral steroids are not the standard approach to an acute MS relapse; a short, high-dose course (typically IV) is used instead, avoiding the adverse effects of prolonged steroid use.', 3),
('e0000000-0000-0000-0000-000000000048', 'D', 'Plasma exchange as first-line treatment', false, 'Ruled out because plasma exchange is reserved for severe relapses that fail to respond to corticosteroids, not as first-line treatment for a typical relapse.', 4),
('e0000000-0000-0000-0000-000000000048', 'E', 'Reassurance only, as relapses always resolve spontaneously', false, 'Ruled out because although many relapses do improve spontaneously over time, a significant, disabling relapse warrants active treatment with corticosteroids to speed recovery.', 5),
('e0000000-0000-0000-0000-000000000049', 'A', 'Multiple sclerosis', false, 'Ruled out because MS typically causes shorter spinal cord lesions (usually less than three vertebral segments) and is not associated with aquaporin-4 antibodies, unlike the longitudinally extensive lesion and positive antibody test described here.', 1),
('e0000000-0000-0000-0000-000000000049', 'B', 'Transverse myelitis in isolation (idiopathic)', false, 'Ruled out because the positive aquaporin-4 antibody and the additional severe bilateral optic neuritis point to a specific underlying diagnosis (NMOSD) rather than an isolated, idiopathic event.', 2),
('e0000000-0000-0000-0000-000000000049', 'C', 'Neuromyelitis optica spectrum disorder', true, 'Correct. Severe, often bilateral optic neuritis, a longitudinally extensive transverse myelitis (spanning three or more vertebral segments), and positive aquaporin-4 antibodies are characteristic of neuromyelitis optica spectrum disorder, a distinct condition from MS with a different underlying immunopathology and treatment approach.', 3),
('e0000000-0000-0000-0000-000000000049', 'D', 'Guillain-Barre syndrome', false, 'Ruled out because GBS is a peripheral (not central) process without optic nerve or spinal cord MRI lesions, and is not associated with aquaporin-4 antibodies.', 4),
('e0000000-0000-0000-0000-000000000049', 'E', 'Vitamin B12 deficiency', false, 'Ruled out because B12 deficiency does not cause optic neuritis or a longitudinally extensive spinal cord lesion, and is not linked to aquaporin-4 antibody positivity.', 5),
('e0000000-0000-0000-0000-000000000050', 'A', 'Internuclear ophthalmoplegia', true, 'Correct. Impaired adduction of one eye on contralateral gaze with nystagmus of the abducting fellow eye, and preserved convergence, is the classic sign of internuclear ophthalmoplegia, caused by a lesion of the medial longitudinal fasciculus (here, on the left, impairing left eye adduction) -- a highly characteristic finding in multiple sclerosis in a young patient.', 1),
('e0000000-0000-0000-0000-000000000050', 'B', 'Third cranial nerve palsy', false, 'Ruled out because a third nerve palsy would cause impaired adduction (and other extraocular movements) of the affected eye on all gaze directions, along with ptosis and pupil involvement, not the isolated, gaze-direction-specific pattern described, and convergence would also typically be impaired.', 2),
('e0000000-0000-0000-0000-000000000050', 'C', 'Sixth cranial nerve palsy', false, 'Ruled out because a sixth nerve palsy causes impaired abduction (not adduction) of the affected eye, the opposite pattern to that described.', 3),
('e0000000-0000-0000-0000-000000000050', 'D', 'Myasthenia gravis', false, 'Ruled out because although MG can cause variable diplopia, it would not produce this specific, reproducible pattern linked to a defined brainstem tract (MLF) with preserved convergence, and would typically show fatigability rather than this static localising sign.', 4),
('e0000000-0000-0000-0000-000000000050', 'E', 'Horner syndrome', false, 'Ruled out because Horner syndrome causes ptosis, miosis and anhidrosis, not a disorder of conjugate eye movements or diplopia.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('e0000000-0000-0000-0000-000000000001', 'Face- and arm-predominant weakness with leg relatively spared localises to the MCA territory (lateral cortex), not ACA (leg-predominant) or lacunar (equal, subcortical) strokes.', 1),
('e0000000-0000-0000-0000-000000000001', 'Expressive/receptive language deficit (aphasia) indicates a cortical, dominant-hemisphere lesion -- a feature absent in lacunar or brainstem strokes.', 2),
('e0000000-0000-0000-0000-000000000001', 'Homonymous hemianopia plus hemiparesis plus aphasia together point to a large cortical MCA infarct rather than an isolated lacunar or PCA event.', 3),
('e0000000-0000-0000-0000-000000000002', 'Equal involvement of face, arm and leg (rather than face/arm-predominant) suggests a subcortical, internal-capsule lesion rather than a cortical MCA infarct.', 1),
('e0000000-0000-0000-0000-000000000002', 'Absence of cortical signs (aphasia, neglect, visual field defect) rules out the larger anterior circulation syndromes (TACI/PACI).', 2),
('e0000000-0000-0000-0000-000000000002', 'Vascular risk factors (hypertension, diabetes) are the classic drivers of the small-vessel lipohyalinosis that causes lacunar infarcts.', 3),
('e0000000-0000-0000-0000-000000000003', '"Crossed" sensory findings -- ipsilateral face, contralateral body -- localise the lesion to the brainstem, not the cortex or spinal cord.', 1),
('e0000000-0000-0000-0000-000000000003', 'Ipsilateral Horner syndrome plus bulbar signs (dysphagia, hoarseness) point specifically to the lateral medulla.', 2),
('e0000000-0000-0000-0000-000000000003', 'Vertigo, vomiting and ataxia without limb weakness reflect vestibular and cerebellar peduncle involvement, distinguishing this from an anterior circulation stroke.', 3),
('e0000000-0000-0000-0000-000000000004', 'Complete resolution of focal neurological symptoms within 24 hours (typically minutes) defines a TIA rather than a completed stroke.', 1),
('e0000000-0000-0000-0000-000000000004', 'Vascular risk factors (hypertension, diabetes) and a recent TIA raise the early stroke risk, driving the need for assessment within 24 hours rather than routine referral.', 2),
('e0000000-0000-0000-0000-000000000004', 'Aspirin 300 mg is given immediately, before specialist review, unless there is a bleeding risk or the patient is already on anticoagulation.', 3),
('e0000000-0000-0000-0000-000000000005', 'Presentation within 4.5 hours of clearly defined symptom onset is the key time-based eligibility criterion for thrombolysis.', 1),
('e0000000-0000-0000-0000-000000000005', 'Absence of haemorrhage on CT is mandatory before thrombolysis can be given.', 2),
('e0000000-0000-0000-0000-000000000005', $x$Blood pressure above 185/110 mmHg must be controlled before thrombolysis; this patient's reading does not yet exceed that threshold.$x$, 3),
('e0000000-0000-0000-0000-000000000006', 'Thunderclap onset (maximal intensity within seconds) is the classic red-flag headache pattern for SAH.', 1),
('e0000000-0000-0000-0000-000000000006', 'CT sensitivity for SAH falls with time since onset, so a normal early scan does not exclude the diagnosis.', 2),
('e0000000-0000-0000-0000-000000000006', 'Lumbar puncture must be delayed until at least 12 hours post-onset to reliably detect xanthochromia, avoiding false negatives from an LP performed too early.', 3),
('e0000000-0000-0000-0000-000000000007', 'A lucid interval between initial injury and subsequent rapid deterioration is characteristic of extradural haematoma as the haematoma expands.', 1),
('e0000000-0000-0000-0000-000000000007', 'Biconvex shape and confinement by suture lines (where the dura is tightly adherent) distinguishes extradural from subdural haematoma on imaging.', 2),
('e0000000-0000-0000-0000-000000000007', 'An ipsilateral fixed dilated pupil signals uncal herniation with third cranial nerve compression, a neurosurgical emergency.', 3),
('e0000000-0000-0000-0000-000000000008', 'The postpartum period is a major hypercoagulable state that predisposes to venous (not arterial) thrombosis.', 1),
('e0000000-0000-0000-0000-000000000008', 'Papilloedema with a postural headache (worse lying flat) reflects raised intracranial pressure from impaired venous drainage.', 2),
('e0000000-0000-0000-0000-000000000008', 'Focal seizures in this context suggest venous infarction or haemorrhage, distinguishing this from IIH, which does not typically cause seizures.', 3),
('e0000000-0000-0000-0000-000000000009', 'Neck pain following mechanical trauma or hyperextension in a young patient is a classic trigger for arterial dissection.', 1),
('e0000000-0000-0000-0000-000000000009', 'A partial Horner syndrome (ptosis and miosis without anhidrosis) reflects disruption of the sympathetic plexus around the internal carotid artery.', 2),
('e0000000-0000-0000-0000-000000000009', 'A delay of hours to days between the local signs (pain, Horner) and the onset of stroke symptoms reflects secondary thromboembolism from the dissection site.', 3),
('e0000000-0000-0000-0000-000000000010', 'Prolonged postictal confusion (many minutes) strongly favours seizure; syncope recovery is typically rapid.', 1),
('e0000000-0000-0000-0000-000000000010', 'Lateral tongue biting is more specific for epileptic seizure than incontinence or jerking, which can occur in convulsive syncope too.', 2),
('e0000000-0000-0000-0000-000000000010', 'A trigger (prolonged standing, pain, emotional stress) and a brief prodrome (light-headedness, tunnel vision) favour syncope over seizure.', 3),
('e0000000-0000-0000-0000-000000000011', 'An epigastric rising sensation and deja vu are classic auras localising to the temporal lobe (often mesial temporal/hippocampal).', 1),
('e0000000-0000-0000-0000-000000000011', 'Automatisms (lip-smacking, fumbling) with impaired but not fully lost awareness, followed by amnesia, are typical of a focal seizure with impaired awareness.', 2),
('e0000000-0000-0000-0000-000000000011', 'Lack of a prior warning aura and abrupt onset/offset without postictal confusion would instead suggest absence seizures, not present here.', 3),
('e0000000-0000-0000-0000-000000000012', 'Seizure activity continuing beyond 5 minutes (or repeated seizures without recovery) defines status epilepticus and mandates treatment, not observation.', 1),
('e0000000-0000-0000-0000-000000000012', 'IV lorazepam is the preferred first-line agent once IV access is secured, even if buccal/rectal benzodiazepines were already given pre-hospital.', 2),
('e0000000-0000-0000-0000-000000000012', 'Second-line agents (phenytoin, levetiracetam, valproate) are reserved for seizures persisting despite two doses of benzodiazepine.', 3),
('e0000000-0000-0000-0000-000000000013', 'Onset in adolescence with morning myoclonic jerks is the hallmark presentation of juvenile myoclonic epilepsy.', 1),
('e0000000-0000-0000-0000-000000000013', 'Sensitivity to sleep deprivation and alcohol as seizure triggers is characteristic of this syndrome.', 2),
('e0000000-0000-0000-0000-000000000013', 'Generalised polyspike-and-wave discharges on EEG (rather than focal discharges or the 3 Hz spike-wave of absence epilepsy) supports this specific generalised epilepsy syndrome.', 3),
('e0000000-0000-0000-0000-000000000014', 'Abrupt onset and offset without any aura or postictal confusion is characteristic of absence seizures, distinguishing them from focal seizures.', 1),
('e0000000-0000-0000-0000-000000000014', 'Provocation by hyperventilation and a generalised 3 Hz spike-and-wave EEG pattern are diagnostic of typical absence epilepsy.', 2),
('e0000000-0000-0000-0000-000000000014', 'Onset in mid-childhood (rather than adolescence) and lack of convulsive motor activity distinguish this from juvenile myoclonic epilepsy.', 3),
('e0000000-0000-0000-0000-000000000015', $x$Any seizure requires the patient to stop driving a Group 1 vehicle and notify the DVLA themselves -- the doctor's role is to advise the patient of this duty.$x$, 1),
('e0000000-0000-0000-0000-000000000015', 'A single unprovoked seizure with normal MRI and EEG carries a shorter mandatory seizure-free period (6 months) than an established epilepsy diagnosis (typically 12 months).', 2),
('e0000000-0000-0000-0000-000000000015', 'Group 2 (HGV/PCV) licence rules are substantially stricter than Group 1 and are not addressed by the same 6-month rule.', 3),
('e0000000-0000-0000-0000-000000000016', 'Sodium valproate carries the highest teratogenic risk (including neural tube defects) and neurodevelopmental risk among commonly used antiepileptics.', 1),
('e0000000-0000-0000-0000-000000000016', 'Pre-conception planning allows a safer alternative to be trialled and stabilised before pregnancy, rather than switching once pregnant.', 2),
('e0000000-0000-0000-0000-000000000016', 'Uncontrolled seizures in pregnancy carry their own maternal and fetal risks, so abrupt cessation of all treatment is not appropriate.', 3),
('e0000000-0000-0000-0000-000000000017', $x$Weakness confined to the same body part involved in the seizure, appearing immediately afterwards, is characteristic of Todd's paresis.$x$, 1),
('e0000000-0000-0000-0000-000000000017', 'Spontaneous, gradual resolution over hours (up to 48 hours) without any new lesion on imaging supports a postictal rather than structural cause.', 2),
('e0000000-0000-0000-0000-000000000017', 'A clear temporal link to a witnessed seizure event distinguishes this from an independent stroke or TIA.', 3),
('e0000000-0000-0000-0000-000000000018', 'Gradual spread of positive visual phenomena over 15-30 minutes (cortical spreading depression) is characteristic of migraine aura, unlike the sudden onset typical of TIA.', 1),
('e0000000-0000-0000-0000-000000000018', 'A throbbing, unilateral headache with nausea and photophobia following the aura fits the migraine pattern rather than cluster or tension headache.', 2),
('e0000000-0000-0000-0000-000000000018', 'Complete resolution between episodes with no interictal deficit argues against a structural or vascular cause requiring urgent imaging.', 3),
('e0000000-0000-0000-0000-000000000019', 'Strictly unilateral, severe periorbital pain with ipsilateral autonomic features (lacrimation, nasal congestion) defines the trigeminal autonomic cephalalgias, of which cluster headache is the prototype.', 1),
('e0000000-0000-0000-0000-000000000019', 'Restlessness and agitation during attacks (in contrast to migraine, where patients prefer stillness) is a classic distinguishing behavioural feature of cluster headache.', 2),
('e0000000-0000-0000-0000-000000000019', 'Clustering of attacks (multiple per day/night over weeks, then remission) distinguishes cluster headache from the more sporadic pattern of migraine.', 3),
('e0000000-0000-0000-0000-000000000020', 'Bilateral, band-like, pressure (not throbbing) pain without aggravation by physical activity distinguishes tension-type headache from migraine.', 1),
('e0000000-0000-0000-0000-000000000020', 'Absence of nausea, vomiting, or photophobia supports tension-type headache over migraine.', 2),
('e0000000-0000-0000-0000-000000000020', 'A normal neurological examination and lack of red-flag features (worse on waking, positional, progressive) makes a secondary cause unlikely.', 3),
('e0000000-0000-0000-0000-000000000021', 'Brief (seconds), severe, electric shock-like pain distinguishes trigeminal neuralgia from the longer-lasting pain of cluster headache or TMJ dysfunction.', 1),
('e0000000-0000-0000-0000-000000000021', 'Provocation by innocuous stimuli (light touch, chewing, cold wind) in a trigeminal nerve distribution is a hallmark trigger pattern.', 2),
('e0000000-0000-0000-0000-000000000021', 'A normal neurological examination, particularly normal facial sensation, is typical of classical (idiopathic) trigeminal neuralgia; sensory loss would raise suspicion of a secondary cause (e.g. compressive lesion, MS).', 3),
('e0000000-0000-0000-0000-000000000022', 'Jaw claudication (pain on chewing that eases with rest) is a highly specific symptom for giant cell arteritis, reflecting ischaemia of the masseter muscles.', 1),
('e0000000-0000-0000-0000-000000000022', 'A markedly raised ESR/CRP in an older patient with a new temporal headache strongly supports GCA over other headache causes.', 2),
('e0000000-0000-0000-0000-000000000022', 'Steroids must be started immediately on clinical suspicion, before biopsy confirmation, because of the risk of sudden irreversible visual loss if treatment is delayed.', 3),
('e0000000-0000-0000-0000-000000000023', 'Obesity in a woman of reproductive age is the classic epidemiological risk profile for idiopathic intracranial hypertension.', 1),
('e0000000-0000-0000-0000-000000000023', 'Papilloedema with pulsatile tinnitus and a normal MRI (excluding structural causes) points to a CSF pressure disorder rather than a mass lesion.', 2),
('e0000000-0000-0000-0000-000000000023', 'A raised opening pressure with otherwise normal CSF constituents (cell count, protein, glucose) confirms IIH and excludes infective or inflammatory causes.', 3),
('e0000000-0000-0000-0000-000000000024', 'Fatigability -- symptoms worsening with sustained or repeated activity and improving with rest -- is the hallmark of a neuromuscular junction disorder such as myasthenia gravis.', 1),
('e0000000-0000-0000-0000-000000000024', 'Ocular and bulbar muscles (ptosis, diplopia, chewing/swallowing fatigue) are characteristically affected early and prominently in myasthenia gravis.', 2),
('e0000000-0000-0000-0000-000000000024', 'Anti-AChR antibodies are positive in the large majority of generalised myasthenia gravis cases, making this the most likely antibody as opposed to the rarer anti-MuSK subtype.', 3),
('e0000000-0000-0000-0000-000000000025', 'Post-tetanic potentiation -- an initially reduced or absent reflex/power that transiently improves after sustained contraction -- is a specific electrophysiological and clinical hallmark of Lambert-Eaton myasthenic syndrome.', 1),
('e0000000-0000-0000-0000-000000000025', 'Autonomic symptoms (dry mouth, constipation, erectile dysfunction) frequently accompany LEMS, distinguishing it from myasthenia gravis.', 2),
('e0000000-0000-0000-0000-000000000025', 'Strong association with small cell lung cancer (paraneoplastic, via antibodies against presynaptic voltage-gated calcium channels) should prompt a search for underlying malignancy.', 3),
('e0000000-0000-0000-0000-000000000026', 'A preceding diarrhoeal (or respiratory) infection roughly 1-3 weeks before onset is a classic trigger for the post-infectious, immune-mediated demyelination of GBS.', 1),
('e0000000-0000-0000-0000-000000000026', 'Progressive, symmetric, ascending weakness with reduced/absent reflexes distinguishes GBS from other causes of acute weakness.', 2),
('e0000000-0000-0000-0000-000000000026', 'Falling forced vital capacity signals impending respiratory failure and is the key parameter that determines the need for escalation to critical care, regardless of limb power.', 3),
('e0000000-0000-0000-0000-000000000027', 'Simultaneous upper motor neuron (brisk reflexes, extensor plantar) and lower motor neuron (wasting, fasciculations) signs in the same anatomical region is the defining diagnostic clue for motor neuron disease.', 1),
('e0000000-0000-0000-0000-000000000027', 'Complete absence of sensory symptoms or signs, despite significant motor involvement, is a key feature distinguishing MND from radiculopathy, neuropathy, or myelopathy.', 2),
('e0000000-0000-0000-0000-000000000027', 'Preserved cognition alongside pure motor involvement helps distinguish typical ALS from other neurodegenerative conditions with combined cognitive and motor features.', 3),
('e0000000-0000-0000-0000-000000000028', 'Sensory symptoms confined to the median nerve distribution (thumb, index, middle, and radial half of ring finger) localise the problem to the wrist, not a more proximal nerve root or brachial plexus lesion.', 1),
('e0000000-0000-0000-0000-000000000028', 'Nocturnal worsening relieved by shaking the hand ("flick sign") is a classically described feature of carpal tunnel syndrome.', 2),
('e0000000-0000-0000-0000-000000000028', 'Pregnancy is a recognised risk factor for carpal tunnel syndrome due to fluid retention causing compression within the carpal tunnel.', 3),
('e0000000-0000-0000-0000-000000000029', 'A lifelong history from childhood with a similarly affected parent points to a hereditary, not acquired, peripheral neuropathy.', 1),
('e0000000-0000-0000-0000-000000000029', 'Pes cavus and distal leg wasting ("inverted champagne bottle" legs) are classic skeletal and muscular findings of Charcot-Marie-Tooth disease, reflecting longstanding distal denervation.', 2),
('e0000000-0000-0000-0000-000000000029', 'A length-dependent, symmetric, distal sensorimotor pattern is typical of this and other peripheral polyneuropathies, as opposed to an acute or central process.', 3),
('e0000000-0000-0000-0000-000000000030', 'A symmetric, "stocking" (length-dependent) distribution of sensory loss reflects the distal-predominant pattern typical of diabetic and other metabolic polyneuropathies.', 1),
('e0000000-0000-0000-0000-000000000030', 'Longstanding, poorly controlled diabetes is the strongest single risk factor and contextual clue pointing to a diabetic rather than hereditary or inflammatory cause.', 2),
('e0000000-0000-0000-0000-000000000030', 'Preserved motor power with prominent sensory loss and absent ankle reflexes reflects a predominantly sensory polyneuropathy, in contrast to the predominantly motor pattern seen in GBS.', 3),
('e0000000-0000-0000-0000-000000000031', $x$Bilateral cortical innervation of the forehead muscles means an upper motor neuron (stroke) lesion spares the forehead, while a lower motor neuron lesion (Bell's palsy) affects the whole side of the face, including the forehead.$x$, 1),
('e0000000-0000-0000-0000-000000000031', $x$Inability to close the eye and inability to raise the eyebrow together indicate complete ipsilateral facial nerve (lower motor neuron) involvement, as seen in Bell's palsy.$x$, 2),
('e0000000-0000-0000-0000-000000000031', 'Additional signs such as limb weakness or dysarthria would suggest a central (stroke) cause instead, but their absence alone does not exclude a small, isolated brainstem stroke.', 3),
('e0000000-0000-0000-0000-000000000032', 'A clear history of prolonged compression over the spiral groove of the humerus (e.g. arm draped over a chair, deep sleep) is a classic precipitant for radial nerve palsy.', 1),
('e0000000-0000-0000-0000-000000000032', 'Wrist and finger drop with preserved triceps power localises the lesion to the radial nerve at or below the spiral groove (triceps is supplied more proximally).', 2),
('e0000000-0000-0000-0000-000000000032', $x$Sensory loss confined to the dorsal first web space is specific to the radial nerve's superficial sensory branch, distinguishing it from median or ulnar neuropathies.$x$, 3),
('e0000000-0000-0000-0000-000000000033', $x$A resting tremor that improves with voluntary movement, rather than worsening (as in essential tremor), is characteristic of Parkinson's disease.$x$, 1),
('e0000000-0000-0000-0000-000000000033', $x$The combination of bradykinesia, rigidity, and resting tremor (the core parkinsonian triad) with a stooped, shuffling gait supports idiopathic Parkinson's disease.$x$, 2),
('e0000000-0000-0000-0000-000000000033', $x$Asymmetric onset (starting on one side) is typical of idiopathic Parkinson's disease, unlike the more symmetric presentations of drug-induced parkinsonism or Parkinson-plus syndromes.$x$, 3),
('e0000000-0000-0000-0000-000000000034', $x$Early, recurrent falls (particularly backward falls) within the first year of symptom onset is atypical for idiopathic Parkinson's disease and points towards a Parkinson-plus syndrome such as PSP.$x$, 1),
('e0000000-0000-0000-0000-000000000034', $x$A supranuclear vertical gaze palsy (especially impaired downgaze) is a specific and characteristic finding of PSP, not seen in idiopathic Parkinson's disease.$x$, 2),
('e0000000-0000-0000-0000-000000000034', $x$A poor or minimal response to levodopa, despite parkinsonian features, is typical of Parkinson-plus syndromes rather than idiopathic Parkinson's disease.$x$, 3),
('e0000000-0000-0000-0000-000000000035', $x$A tremor that is present with sustained posture or action but improves at complete rest is the opposite pattern to the resting tremor of Parkinson's disease.$x$, 1),
('e0000000-0000-0000-0000-000000000035', 'Improvement with a small amount of alcohol is a classically described and relatively specific feature of essential tremor.', 2),
('e0000000-0000-0000-0000-000000000035', 'A positive family history (often autosomal dominant inheritance) is common in essential tremor, supporting the diagnosis alongside the absence of bradykinesia or rigidity.', 3),
('e0000000-0000-0000-0000-000000000036', $x$Chorea combined with progressive cognitive/psychiatric decline is characteristic of Huntington's disease.$x$, 1),
('e0000000-0000-0000-0000-000000000036', $x$A strong family history with autosomal dominant inheritance (and often anticipation, with earlier/more severe onset in successive generations) supports Huntington's disease over an acquired cause.$x$, 2),
('e0000000-0000-0000-0000-000000000036', $x$Onset in mid-adulthood with a relentlessly progressive course distinguishes this from self-limiting chorea (e.g. Sydenham's) seen in younger patients.$x$, 3),
('e0000000-0000-0000-0000-000000000037', $x$The combination of a movement disorder, psychiatric change, and liver dysfunction in a young patient should always prompt consideration of Wilson's disease.$x$, 1),
('e0000000-0000-0000-0000-000000000037', $x$Kayser-Fleischer rings (copper deposition in Descemet's membrane of the cornea) are a highly specific sign of Wilson's disease.$x$, 2),
('e0000000-0000-0000-0000-000000000037', 'Low serum caeruloplasmin reflects the underlying defect in copper transport, confirming the diagnosis alongside the clinical picture.', 3),
('e0000000-0000-0000-0000-000000000038', $x$Symmetric (rather than asymmetric) onset of parkinsonian features is more typical of a secondary cause, such as drug-induced parkinsonism, than idiopathic Parkinson's disease.$x$, 1),
('e0000000-0000-0000-0000-000000000038', 'A clear temporal relationship to starting a dopamine receptor-blocking drug (typical antipsychotics, some antiemetics) is the key diagnostic clue.', 2),
('e0000000-0000-0000-0000-000000000038', 'Absence of early falls or gaze palsy makes a Parkinson-plus syndrome (such as PSP) less likely, supporting a simpler drug-induced explanation.', 3),
('e0000000-0000-0000-0000-000000000039', 'An urge to move the legs accompanying an unpleasant sensation, specifically relieved by movement, is the core diagnostic feature of restless legs syndrome.', 1),
('e0000000-0000-0000-0000-000000000039', 'A clear worsening at rest and in the evening/night (circadian pattern) is characteristic of RLS.', 2),
('e0000000-0000-0000-0000-000000000039', 'Iron deficiency and chronic kidney disease are recognised secondary causes/associations of restless legs syndrome, and correcting iron deficiency can improve symptoms.', 3),
('e0000000-0000-0000-0000-000000000040', 'A non-blanching purpuric rash in a patient with meningism strongly suggests meningococcal sepsis, a rapidly fatal condition if treatment is delayed.', 1),
('e0000000-0000-0000-0000-000000000040', 'Antibiotics should never be withheld pending confirmatory investigations (LP, CT) in suspected bacterial meningitis with sepsis -- "time is brain (and life)."', 2),
('e0000000-0000-0000-0000-000000000040', 'Reduced consciousness (drowsy but rousable) is itself a relative contraindication to immediate lumbar puncture (risk of coning), reinforcing that antibiotics, not LP, come first.', 3),
('e0000000-0000-0000-0000-000000000041', 'Temporal lobe involvement on MRI, combined with fever, personality change and seizures, is a classic pattern strongly suggestive of HSV encephalitis.', 1),
('e0000000-0000-0000-0000-000000000041', 'Empirical aciclovir must be started immediately on clinical suspicion, as delay significantly worsens outcome, and treatment should never wait for PCR confirmation.', 2),
('e0000000-0000-0000-0000-000000000041', 'The rapid progression and high mortality/morbidity of untreated HSV encephalitis distinguishes it from more indolent causes of confusion, mandating urgent empirical therapy.', 3),
('e0000000-0000-0000-0000-000000000042', 'A non-blanching, rapidly spreading purpuric rash with fever in a child is a hallmark of meningococcal septicaemia, a rapidly fatal condition without prompt treatment.', 1),
('e0000000-0000-0000-0000-000000000042', 'Pre-hospital benzylpenicillin is specifically recommended when hospital transfer will be delayed, to reduce mortality from bacteraemia.', 2),
('e0000000-0000-0000-0000-000000000042', 'The urgency of the clinical picture (drowsiness, spreading rash) outweighs any need to confirm the diagnosis before starting treatment.', 3),
('e0000000-0000-0000-0000-000000000043', 'A contiguous source of infection (chronic otitis media, sinusitis) is a classic route by which bacteria spread directly to form a brain abscess in the adjacent temporal lobe or cerebellum.', 1),
('e0000000-0000-0000-0000-000000000043', 'Fever combined with a ring-enhancing lesion and focal neurological signs points towards an infective process rather than a primary tumour.', 2),
('e0000000-0000-0000-0000-000000000043', 'A subacute (days to weeks) progressive course with systemic (fever) and focal neurological features is typical of brain abscess, distinguishing it from the more chronic progression typical of a glioma.', 3),
('e0000000-0000-0000-0000-000000000044', 'A subacute course over days to weeks (rather than the acute hours-long onset of bacterial meningitis) is typical of tuberculous meningitis.', 1),
('e0000000-0000-0000-0000-000000000044', 'CSF showing lymphocytic pleocytosis with markedly raised protein and a low glucose (in contrast to the normal glucose typical of viral meningitis) points strongly to TB or another granulomatous/fungal cause.', 2),
('e0000000-0000-0000-0000-000000000044', 'Epidemiological risk (residence in or recent travel from a high-TB-prevalence area) with systemic features (weight loss) supports tuberculosis specifically as the underlying cause.', 3),
('e0000000-0000-0000-0000-000000000045', 'Two separate clinical episodes affecting different parts of the central nervous system, separated by more than one month, fulfil "dissemination in time" for an MS diagnosis.', 1),
('e0000000-0000-0000-0000-000000000045', 'MRI lesions in multiple, anatomically distinct locations (periventricular, juxtacortical, infratentorial, spinal cord) fulfil "dissemination in space."', 2),
('e0000000-0000-0000-0000-000000000045', 'A mixture of enhancing (active/recent) and non-enhancing (older) lesions on a single MRI can itself demonstrate dissemination in time, supporting the diagnosis even without waiting for a second clinical relapse.', 3),
('e0000000-0000-0000-0000-000000000046', 'Pain on eye movement accompanying visual loss is a classic feature of optic neuritis, reflecting inflammation of the optic nerve within its dural sheath.', 1),
('e0000000-0000-0000-0000-000000000046', 'A relative afferent pupillary defect (Marcus Gunn pupil) indicates a lesion of the optic nerve (afferent visual pathway) on the affected side.', 2),
('e0000000-0000-0000-0000-000000000046', 'Reduced colour vision, particularly red desaturation, disproportionate to visual acuity loss, is a sensitive early sign of optic nerve dysfunction.', 3),
('e0000000-0000-0000-0000-000000000047', 'A clearly defined sensory level on examination localises the lesion to a specific spinal cord segment, distinguishing this from a peripheral neuropathy (GBS) which lacks a sensory level.', 1),
('e0000000-0000-0000-0000-000000000047', 'Rapid (over hours to days) bilateral motor, sensory and bladder involvement reflects an acute transverse (across the full width of the cord) process.', 2),
('e0000000-0000-0000-0000-000000000047', 'An inflammatory-appearing lesion on MRI (rather than a compressive structural lesion) supports an inflammatory/demyelinating aetiology such as transverse myelitis.', 3),
('e0000000-0000-0000-0000-000000000048', 'Before treating a presumed relapse, it is important to exclude an underlying infection (e.g. urinary tract infection), which can cause a pseudo-relapse without true new inflammation.', 1),
('e0000000-0000-0000-0000-000000000048', 'High-dose corticosteroids shorten the duration of a relapse and hasten recovery but do not alter the long-term disease trajectory or disability accumulation.', 2),
('e0000000-0000-0000-0000-000000000048', 'Disease-modifying therapies act over the long term to reduce relapse frequency and are not appropriate acute treatments for a current relapse.', 3),
('e0000000-0000-0000-0000-000000000049', 'A longitudinally extensive spinal cord lesion (spanning three or more vertebral segments) is a key MRI feature distinguishing NMOSD from the shorter, more localised lesions typical of MS.', 1),
('e0000000-0000-0000-0000-000000000049', 'Positive aquaporin-4 antibodies are highly specific for neuromyelitis optica spectrum disorder and are not found in typical MS.', 2),
('e0000000-0000-0000-0000-000000000049', 'Severe, often bilateral or sequential optic neuritis with poor recovery is more typical of NMOSD than the usually unilateral, better-recovering optic neuritis of MS.', 3),
('e0000000-0000-0000-0000-000000000050', 'Failure of adduction of one eye with nystagmus of the contralateral abducting eye on lateral gaze is a highly specific sign localising to the medial longitudinal fasciculus.', 1),
('e0000000-0000-0000-0000-000000000050', 'Preserved convergence, despite impaired adduction on lateral gaze, distinguishes an INO (an internuclear tract lesion) from a true third nerve palsy (which would impair convergence too).', 2),
('e0000000-0000-0000-0000-000000000050', 'Internuclear ophthalmoplegia, especially if bilateral, is highly suggestive of multiple sclerosis in a young patient, though it can also occur from brainstem stroke in older patients.', 3);
